import org.junit.jupiter.api.TestFactory;

class GraphSourceDelegationTest {
	@TestFactory
	Stream<DynamicTest> onlyMandatoryPositiveBodiesProveSingleSourceMembership() {
		return Stream.of(
				"?s <urn:p> ?o", "?s <urn:p> ?o . ?s <urn:q> ?v", "VALUES ?v { 1 UNDEF } ?s <urn:p> ?o",
				"", "VALUES ?v { 1 }", "VALUES ?g { <urn:g> } ?s <urn:p> ?o",
				"?s <urn:p> ?o FILTER(true)", "OPTIONAL { ?s <urn:p> ?o }", "?s <urn:p> ?o MINUS { ?s <urn:q> ?v }",
				"{ ?s <urn:p> ?o } UNION { ?s <urn:q> ?v }", "{ SELECT ?s WHERE { ?s <urn:p> ?o } }",
				"GRAPH ?inner { ?s <urn:p> ?o }", "SERVICE <urn:remote> { ?s <urn:p> ?o }", "?s <urn:p>+ ?o")
				.map(body -> DynamicTest.dynamicTest(body.isEmpty() ? "empty" : body, () -> {
					Graph[] selected = new Graph[1];
					QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
							"SELECT * WHERE { GRAPH ?g { " + body + " } }", null)
							.getTupleExpr()
							.visit(new AbstractQueryModelVisitor<RuntimeException>() {
								@Override
								public void meet(Graph graph) {
									selected[0] = graph;
								}
							});
					boolean positive = List.of("?s <urn:p> ?o", "?s <urn:p> ?o . ?s <urn:q> ?v",
							"VALUES ?v { 1 UNDEF } ?s <urn:p> ?o").contains(body);
					assertThat(GenericInfoOptimizer.hasMandatoryPositiveGraphBody(selected[0].getArg(), "g"))
							.isEqualTo(positive);
				}));
	}

	@Test
	void namedAndContextBearingLeavesDoNotProveOuterGraphMembership() {
		for (var scope : StatementPattern.Scope.values()) {
			StatementPattern pattern = new StatementPattern(scope, new Var("s"), new Var("p"), new Var("o"),
					new Var("inner"));
			assertThat(GenericInfoOptimizer.hasMandatoryPositiveGraphBody(pattern, "g")).isFalse();
		}
		assertThat(GenericInfoOptimizer.hasMandatoryPositiveGraphBody(new StatementPattern(
				StatementPattern.Scope.NAMED_CONTEXTS, new Var("s"), new Var("p"), new Var("o")), "g"))
						.isFalse();
	}

	@Test
	void repeatableValuesMustIncludeUndeclaredRowColumnsInTheProof() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("marker"));
		MapBindingSet row = new MapBindingSet();
		row.addBinding("g", SimpleValueFactory.getInstance().createIRI("urn:g"));
		values.setBindingSets(List.of(row));
		assertThat(GenericInfoOptimizer.hasMandatoryPositiveGraphBody(new Join(values,
				new StatementPattern(new Var("s"), new Var("p"), new Var("o"))), "g")).isFalse();
	}

	@Test
	void unknownStreamingValuesCannotProveDisjointColumns() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("marker"));
		values.setBindingSets(() -> {
			throw new AssertionError("Do not consume streaming assignments during proof");
		});
		assertThat(GenericInfoOptimizer.hasMandatoryPositiveGraphBody(new Join(values,
				new StatementPattern(new Var("s"), new Var("p"), new Var("o"))), "g")).isFalse();
	}
}
